import { processJob } from './src/worker.js';
const events=[];
const job={id:'j1', execute:async()=>{events.push('execute'); return 42;}};
const queue={ack:async id=>events.push('ack:'+id)};
const ledger={record:async()=>{events.push('record'); throw new Error('ledger unavailable')}};
try { await processJob(job,queue,ledger); } catch (e) { console.log('error:',e.message); }
console.log('events:',events.join(' -> '));
EOF"

